cat > /srv/legacy2/inode-cache-retention/bin/prune <<'ANTRIEB_PRUNE_EOF'
#!/usr/bin/perl
use strict;
use warnings;
use Cwd qw(abs_path);
use File::Basename qw(dirname);

@ARGV == 1 or die "usage: $0 CUTOFF_EPOCH\n";
my $cutoff = shift;
$cutoff =~ /\A[0-9]+\z/
    or die "cutoff epoch must be a non-negative integer\n";

my $base = abs_path(dirname($0) . "/..")
    or die "cannot resolve installation directory: $!\n";
my $cache = "$base/cache";
my $active_file = "$base/active.txt";

open my $active_fh, "<", $active_file
    or die "cannot open $active_file: $!\n";
my %active;
while (my $name = <$active_fh>) {
    $name =~ s/\r?\n\z//;
    next if $name eq "";
    $active{$name} = 1;
}
close $active_fh or die "cannot close $active_file: $!\n";

opendir my $cache_dh, $cache
    or die "cannot open $cache: $!\n";
my $removed = 0;
while (defined(my $name = readdir $cache_dh)) {
    next if $name eq "." or $name eq "..";
    next unless $name =~ /\.thumb\z/;
    next if exists $active{$name};

    my $path = "$cache/$name";
    my @metadata = lstat $path;
    next unless @metadata;
    next unless -f _ or -l _;
    next unless $metadata[9] < $cutoff;

    unlink $path or die "cannot remove $path: $!\n";
    $removed++;
}
closedir $cache_dh or die "cannot close $cache: $!\n";

print "removed $removed cache entries\n";
ANTRIEB_PRUNE_EOF
chmod 755 /srv/legacy2/inode-cache-retention/bin/prune
/usr/bin/perl -c /srv/legacy2/inode-cache-retention/bin/prune
sed -n '1,240p' /srv/legacy2/inode-cache-retention/bin/prune

